// app/margins/margin-chart.tsx
'use client'

import { DotHistogram, thresholds } from 'tally-charts'

const bands = thresholds(
  [10, 25, 38],
  ['loss', 'warn', 'accent-soft', 'gain'],
  ['Critical', 'At risk', 'Below target', 'On target'],
)

export function MarginChart({ jobs }: { jobs: { id: string; margin: number }[] }) {
  return (
    <DotHistogram
      title="Jobs by margin"
      data={jobs}
      value="margin"
      toneBy={bands}
      format={(v) => `${v}%`}
    />
  )
}

// app/margins/page.tsx (a Server Component, no directive)
import { MarginChart } from './margin-chart'

export default async function Page() {
  const jobs = await loadJobs()
  return <MarginChart jobs={jobs} />
}
